// CHECK-NEXT:    switch i32 [[TMP0]], label %[[SW_EPILOG:.*]] [
// CHECK-NEXT:      i32 0, label %[[SW_BB:.*]]
// CHECK-NEXT:    ]
// CHECK:       [[SW_BB]]:
// CHECK-NEXT:    br label %[[FOR_COND:.*]]
// CHECK:       [[FOR_COND]]:
