// CHECK:       [[SW_EPILOG]]:
// CHECK-NEXT:    br label %[[WHILE_COND]]
// CHECK:       [[WHILE_END]]:
// CHECK-NEXT:    ret void
//
void switch_continue(int n) {
  while (cond())
    switch (n) {
    case 0:
      for (; cond(); ({ continue; })) {}
    }
}

// CHECK-LABEL: define dso_local void @loop_in_condition(
// CHECK-SAME: ) #[[ATTR0]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    [[TMP:%.*]] = alloca i32, align 4
// CHECK-NEXT:    br label %[[WHILE_COND:.*]]
