// CHECK:       [[WHILE_BODY]]:
// CHECK-NEXT:    br label %[[WHILE_COND1:.*]]
// CHECK:       [[WHILE_COND1]]:
// CHECK-NEXT:    br label %[[DO_BODY:.*]]
// CHECK:       [[DO_BODY]]:
// CHECK-NEXT:    br label %[[DO_END:.*]]
// CHECK:       [[DO_COND:.*:]]
// CHECK-NEXT:    [[CALL2:%.*]] = call i32 @cond()
// CHECK-NEXT:    [[TOBOOL3:%.*]] = icmp ne i32 [[CALL2]], 0
// CHECK-NEXT:    br i1 [[TOBOOL3]], label %[[DO_BODY]], label %[[DO_END]]
// CHECK:       [[DO_END]]:
// CHECK-NEXT:    br label %[[WHILE_COND]]
// CHECK:       [[BB0:.*:]]
// CHECK-NEXT:    store i32 1, ptr [[TMP]], align 4
// CHECK-NEXT:    [[TMP1:%.*]] = load i32, ptr [[TMP]], align 4
// CHECK-NEXT:    [[TOBOOL4:%.*]] = icmp ne i32 [[TMP1]], 0
// CHECK-NEXT:    br i1 [[TOBOOL4]], label %[[WHILE_BODY5:.*]], label %[[WHILE_END:.*]]
// CHECK:       [[WHILE_BODY5]]:
// CHECK-NEXT:    br label %[[WHILE_COND1]]
// CHECK:       [[WHILE_END]]:
// CHECK-NEXT:    br label %[[WHILE_COND]]
// CHECK:       [[WHILE_END6]]:
// CHECK-NEXT:    ret void
//
void loop_in_condition(void) {
  while (cond())
    while (({ do { break; } while (cond()); continue; 1; })) {}
}

